Code.Terraform:
```hcl
resource "oci_analytics_analytics_instance" "example" {
  compartment_id    = "<example_resource_id>"
  name              = "<example_resource_name>"
  feature_set       = "ENTERPRISE_ANALYTICS"
  license_type      = "LICENSE_INCLUDED"
  idcs_access_token = "<example_resource_id>"

  capacity {
    capacity_type  = "OLPU_COUNT"
    capacity_value = 1
  }

  network_endpoint_details {
    network_endpoint_type = "PUBLIC"
    whitelisted_ips       = ["<example_resource_id>"] # Critical: restrict to specific allowed CIDR; not 0.0.0.0/0
  }
}
```

```hcl
resource "oci_audit_configuration" "<example_resource_name>" {
  compartment_id        = var.tenancy_ocid
  retention_period_days = 365 # Critical: sets audit log retention to 365 days to pass the check
}
```

```hcl
resource "oci_core_boot_volume_kms_key" "<example_resource_name>" {
  boot_volume_id = "<example_resource_id>"  # Critical: target boot volume to update
  kms_key_id     = "<example_resource_id>"  # Critical: assigns a Customer Managed Key (CMK) to the boot volume
}
```

